  if (sticks.length < 1 || sticks.length > 10000) return 'sticks needs 1 to 10^4 lengths.';
  if (sticks.some(v => !Number.isInteger(v) || v < 1 || v > 10000)) return 'Each length is between 1 and 10^4.';
