function connectSticks(sticks) {
  // Up to 6 sticks: try every order of fusing (memoised on the sorted lengths).
  if (sticks.length <= 6) {
    const memo = new Map();
    const best = (list) => {
      if (list.length === 1) return 0;
      const key = list.join(',');
      if (memo.has(key)) return memo.get(key);
      let result = Infinity;
      for (let i = 0; i < list.length; i++)
        for (let j = i + 1; j < list.length; j++) {
          const rest = list.filter((_, k) => k !== i && k !== j);
          rest.push(list[i] + list[j]);
          rest.sort((a, b) => a - b);
          result = Math.min(result, list[i] + list[j] + best(rest));
        }
      memo.set(key, result);
      return result;
    };
    return best([...sticks].sort((a, b) => a - b));
  }
  // Larger inputs: re-sort every round and fuse the two shortest.
  const list = [...sticks];
  let total = 0;
  while (list.length > 1) {
    list.sort((a, b) => a - b);
    const joined = list.shift() + list.shift();
    total += joined;
    list.push(joined);
  }
  return total;
}

