function generate(rand, size) {
  if (size === 'large') return [Array.from({ length: 2000 }, () => 1 + Math.floor(rand() * 10000))];
  const n = 1 + Math.floor(rand() * 6);
  const top = rand() < 0.3 ? 10000 : 1 + Math.floor(rand() * 12);
  return [Array.from({ length: n }, () => 1 + Math.floor(rand() * top))];
}
